// The camera's rules, kept apart from the camera itself so they can be tested without a camera.
// The team's idea: the camera has triggers; when the person sleeps it does not react, when the person
// grabs their chest it reacts and starts the automation, which calls the doctor.
// The rules below and their thresholds are Claude's technical choice for a demonstration. They are not
// validated: published work found no camera rule for chest grabbing tested on real patients.
// Code generated by Claude (Anthropic), an AI system.

export const RULES = {
  chestSeconds: 1.5, // a hand held on the chest at least this long counts as "hand on chest" (the team's "grabbed the chest")
  sleepSeconds: 5, // eyes closed and almost no movement at least this long counts as "asleep"
  eyesClosed: 0.5, // how sure the face model must be that each eye is closed (0 to 1)
  stillShare: 0.03, // "almost no movement": the nose moves less than this share of the picture width
  stillWindowSeconds: 2, // ... over this many last seconds
  rearmSeconds: 3, // after an event, the rule fires again only after its condition was off this long
};

// Point numbers in MediaPipe's 33-point body model.
export const POINT = { nose: 0, lShoulder: 11, rShoulder: 12, lWrist: 15, rWrist: 16, lIndex: 19, rIndex: 20, lHip: 23, rHip: 24 };

const seen = (pt) => Boolean(pt) && Number.isFinite(pt.x) && Number.isFinite(pt.y) && (pt.visibility === undefined || pt.visibility > 0.5);

// The chest area in picture coordinates (0 to 1), from the shoulders and, if visible, the hips.
// A laptop camera often shows only the upper body; then the torso length is guessed from the shoulders.
export function chestBox(points) {
  if (!points) return null;
  const ls = points[POINT.lShoulder];
  const rs = points[POINT.rShoulder];
  if (!seen(ls) || !seen(rs)) return null;
  const width = Math.abs(ls.x - rs.x);
  if (width < 0.03) return null;
  const top = Math.min(ls.y, rs.y);
  const hips = [points[POINT.lHip], points[POINT.rHip]].filter(seen).map((p) => p.y).filter((y) => y > top);
  const torso = hips.length ? Math.max(...hips) - top : width * 1.2;
  return { x0: Math.min(ls.x, rs.x) - width * 0.1, x1: Math.max(ls.x, rs.x) + width * 0.1, y0: top - torso * 0.05, y1: top + torso * 0.55 };
}

// True when a wrist or an index finger is inside the chest area.
export function handOnChest(points) {
  const box = chestBox(points);
  if (!box) return false;
  const inside = (pt) => seen(pt) && pt.x >= box.x0 && pt.x <= box.x1 && pt.y >= box.y0 && pt.y <= box.y1;
  return [POINT.lWrist, POINT.rWrist, POINT.lIndex, POINT.rIndex].some((i) => inside(points[i]));
}

// True when the face model says both eyes are closed.
export function eyesClosed(blendshapes, threshold = RULES.eyesClosed) {
  if (!Array.isArray(blendshapes)) return false;
  const score = (name) => {
    const hit = blendshapes.find((b) => b.categoryName === name);
    return hit ? hit.score : 0;
  };
  return score('eyeBlinkLeft') > threshold && score('eyeBlinkRight') > threshold;
}

// Remembers where the nose was over the last few seconds and says whether the person is almost still.
export function stillness(windowSeconds = RULES.stillWindowSeconds, share = RULES.stillShare) {
  const track = [];
  return {
    update(point, t) {
      if (!seen(point)) { track.length = 0; return false; }
      track.push({ t, x: point.x, y: point.y });
      while (track.length && t - track[0].t > windowSeconds * 1000) track.shift();
      if (track.length < 2 || t - track[0].t < windowSeconds * 1000 * 0.8) return false;
      const xs = track.map((p) => p.x);
      const ys = track.map((p) => p.y);
      return Math.max(...xs) - Math.min(...xs) < share && Math.max(...ys) - Math.min(...ys) < share;
    },
  };
}

// A timer that grows while a condition holds and fires once. It fires again only after the condition
// has been off for `rearmSeconds`, so one long gesture gives one event, not a flood of them.
export function holdTimer(seconds, rearmSeconds = RULES.rearmSeconds) {
  let since = null;
  let offSince = null;
  let fired = false;
  return {
    update(on, t) {
      if (on) {
        offSince = null;
        if (since === null) since = t;
      } else {
        since = null;
        if (offSince === null) offSince = t;
        if (fired && t - offSince >= rearmSeconds * 1000) fired = false;
      }
      const held = since === null ? 0 : (t - since) / 1000;
      if (on && !fired && held >= seconds) {
        fired = true;
        return { held, fire: true };
      }
      return { held, fire: false };
    },
  };
}
